  ) AS v(session_key, expect_ids, plan)
  LOOP
    PERFORM 1
      FROM public.program_routines pr
      JOIN public.programs p ON p.id = pr.program_id
      JOIN public.workout_templates wt ON wt.id = pr.routine_id
     WHERE p.slug = 'muscle_gain' AND pr.session_key = r.session_key
       AND pr.length_plan IS NULL
       AND (SELECT jsonb_agg(e->'exercise_id' ORDER BY ord)
              FROM jsonb_array_elements(wt.exercises) WITH ORDINALITY AS t(e, ord)) = r.expect_ids;
    IF NOT FOUND THEN
      RAISE EXCEPTION '4.3.9G: muscle_gain % does not match the pilot fixture or already has a plan', r.session_key;
    END IF;
    UPDATE public.program_routines pr
       SET length_plan = r.plan, updated_at = now()
      FROM public.programs p
     WHERE p.id = pr.program_id AND p.slug = 'muscle_gain' AND pr.session_key = r.session_key;
    n := n + 1;
  END LOOP;
  IF n <> 13 THEN RAISE EXCEPTION '4.3.9G: expected 13 plans, wrote %', n; END IF;
  IF (SELECT count(*) FROM public.program_routines WHERE length_plan IS NOT NULL) <> 13 THEN
    RAISE EXCEPTION '4.3.9G: unexpected plans outside muscle_gain';
  END IF;
END $$;
